window.CIVIL_SET_DATA["past-10"] = {"title":"Past Paper Set 10","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-10-005","src":"PAST-10-005","text":"The condition for a well-conditioned triangle is that no angle is less than","options":[{"key":"a","text":"60 degree"},{"key":"b","text":"45 degree"},{"key":"c","text":"20 degree"},{"key":"d","text":"30 degree"}],"answer":"d","explanation":"In triangulation, a well-conditioned triangle has no angle smaller than 30° (or larger than 120°), so small angular errors cause little error in the computed sides. The ideal is 60°.","marks":1,"source":{"kind":"past","set":10,"question":5,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q5 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-10-010","src":"PAST-10-010","text":"The moment of inertia of a hollow circular section is","options":[{"key":"a","text":"\\(\\dfrac{\\pi}{8}(R^4 - r^4)\\)"},{"key":"b","text":"\\(\\dfrac{\\pi}{16}(R^4 - r^4)\\)"},{"key":"c","text":"\\(\\dfrac{\\pi}{4}(R^4 - r^4)\\)"},{"key":"d","text":"\\(\\dfrac{\\pi}{64}(R^4 - r^4)\\)"}],"answer":"c","explanation":"About a diameter, \\[\\begin{aligned} I &amp;= \\dfrac{\\pi}{4}(R^4 - r^4) \\\\ &amp;= \\dfrac{\\pi}{64}(D^4 - d^4) \\end{aligned}\\] The polar moment is twice this.","marks":1,"source":{"kind":"past","set":10,"question":10,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q10 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-10-018","src":"PAST-10-018","text":"For 1 m<sup>3</sup> volume of 1:1.5:3 PCC, how many bags of cement are required?","options":[{"key":"a","text":"6 bags"},{"key":"b","text":"8 bags"},{"key":"c","text":"7 bags"},{"key":"d","text":"9 bags"}],"answer":"b","explanation":"The dry volume is 1.54 m<sup>3</sup> for a 1:1.5:3 mix, so \\[\\text{cement} = \\dfrac{1.54}{5.5} = 0.28\\ \\text{m}^3\\] which is about 403 kg, or 8 bags of 50 kg.","marks":1,"source":{"kind":"past","set":10,"question":18,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q18 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-10-022","src":"PAST-10-022","text":"The Vicat apparatus is used in","options":[{"key":"a","text":"compressive strength test"},{"key":"b","text":"consistency test"},{"key":"c","text":"soundness test"},{"key":"d","text":"fineness of cement"}],"answer":"b","explanation":"The Vicat apparatus measures the standard (normal) consistency of cement paste, with a 10 mm plunger, and its initial and final setting times with needles.","marks":1,"source":{"kind":"past","set":10,"question":22,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q22 · 1 mark"},"topic":"ACiE0102"},{"id":"PAST-10-023","src":"PAST-10-023","text":"The strength of timber is maximum in the direction","options":[{"key":"a","text":"across grain"},{"key":"b","text":"perpendicular to the grain"},{"key":"c","text":"parallel to grain"},{"key":"d","text":"same everywhere"}],"answer":"c","explanation":"Timber fibres run along the grain, so its tensile and compressive strengths are greatest parallel to the grain and much lower across it.","marks":1,"source":{"kind":"past","set":10,"question":23,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q23 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-10-029","src":"PAST-10-029","text":"Terracotta is used in buildings for","options":[{"key":"a","text":"ornamental work"},{"key":"b","text":"insulation"},{"key":"c","text":"storage"},{"key":"d","text":"none"}],"answer":"a","explanation":"Terracotta (baked, often glazed clay) is used for ornamental facing blocks, cornices, jali work and decorative panels.","marks":1,"source":{"kind":"past","set":10,"question":29,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q29 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-10-032","src":"PAST-10-032","text":"The early strength of cement is achieved by","options":[{"key":"a","text":"C<sub>3</sub>S"},{"key":"b","text":"C<sub>2</sub>S"},{"key":"c","text":"C<sub>3</sub>A"},{"key":"d","text":"C<sub>4</sub>AF"}],"answer":"a","explanation":"Tricalcium silicate hydrates quickly and gives most of the strength in the first 7 days. C<sub>2</sub>S gives later strength, while C<sub>3</sub>A causes flash set and heat but little strength.","marks":1,"source":{"kind":"past","set":10,"question":32,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q32 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-10-040","src":"PAST-10-040","text":"A revised estimate is prepared when the original sanctioned detailed estimate is exceeded by","options":[{"key":"a","text":"15%"},{"key":"b","text":"10%"},{"key":"c","text":"5%"},{"key":"d","text":"12%"}],"answer":"c","explanation":"A revised estimate is required when the sanctioned estimate is likely to be exceeded by more than 5% (or the scope changes materially). The key follows this common PWD rule.","marks":1,"source":{"kind":"past","set":10,"question":40,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q40 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-10-067","src":"PAST-10-067","text":"Which of them has the maximum influence on steel?","options":[{"key":"a","text":"Phosphorous"},{"key":"b","text":"Iron"},{"key":"c","text":"Aluminium"},{"key":"d","text":"Carbon"}],"answer":"d","explanation":"Carbon content decides the class and properties of steel (mild, medium, high carbon): its strength, hardness, ductility and weldability. Small changes in carbon change them greatly.","marks":2,"source":{"kind":"past","set":10,"question":67,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q67 · 2 marks"},"topic":"ACiE0101"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-10-002","src":"PAST-10-002","text":"The soil of Kathmandu valley is","options":[{"key":"a","text":"Silty clay"},{"key":"b","text":"organic"},{"key":"c","text":"black soil"},{"key":"d","text":"all"}],"answer":"d","explanation":"The valley floor is an old lake (lacustrine) deposit of soft silty clays, with organic and dark ('kalimati', black) clay layers. All the descriptions apply.","marks":1,"source":{"kind":"past","set":10,"question":2,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q2 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-10-014","src":"PAST-10-014","text":"The Culmann graph is used in","options":[{"key":"a","text":"Coulomb wedge theory"},{"key":"b","text":"Rankine theory"},{"key":"c","text":"Culmann theory"},{"key":"d","text":"All"}],"answer":"a","explanation":"Culmann's graphical construction finds the maximum Coulomb wedge thrust on a retaining wall. It is a graphical solution of Coulomb's wedge theory.","marks":1,"source":{"kind":"past","set":10,"question":14,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q14 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-10-035","src":"PAST-10-035","text":"If the depth of foundation is \\(D\\), the bearing capacity of soil does not depend on \\(R_{w1}\\), \\(R_{w2}\\) (water table correction) when the water table is at","options":[{"key":"a","text":"depth \\(D\\) below foundation"},{"key":"b","text":"any depth below foundation"},{"key":"c","text":"any depth below GL"},{"key":"d","text":"all"}],"answer":"a","explanation":"The water table reduces bearing capacity only while it lies within about one footing width below the base. When it is deeper than that (taken here as depth D below the foundation), \\(R_{w1} = R_{w2} = 1\\) and it has no effect.","marks":1,"source":{"kind":"past","set":10,"question":35,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q35 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-10-046","src":"PAST-10-046","text":"A clay is …… if it has been subjected to a pressure in excess of its present pressure.","options":[{"key":"a","text":"post consolidated"},{"key":"b","text":"normally consolidated"},{"key":"c","text":"over consolidated"},{"key":"d","text":"any of above"}],"answer":"c","explanation":"An over-consolidated clay has experienced a past maximum effective stress greater than its present overburden, so OCR &gt; 1.","marks":1,"source":{"kind":"past","set":10,"question":46,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q46 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-10-055","src":"PAST-10-055","text":"The coefficient of uniformity is","options":[{"key":"a","text":"\\(\\dfrac{D_{10}}{D_{60}}\\)"},{"key":"b","text":"\\(\\dfrac{D_{60}}{D_{10}}\\)"},{"key":"c","text":"\\(\\dfrac{D_{30}^2}{D_{60}}\\)"},{"key":"d","text":"\\(\\dfrac{D_{50}}{D_{10}}\\)"}],"answer":"b","explanation":"The coefficients of uniformity and curvature are \\[C_u = \\dfrac{D_{60}}{D_{10}}\\] \\[C_c = \\dfrac{D_{30}^2}{D_{10}D_{60}}\\]","marks":1,"source":{"kind":"past","set":10,"question":55,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q55 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-10-070","src":"PAST-10-070","text":"A dry specimen is put through a tri-axial test with cell pressure = 50 kPa and deviator stress at failure = 100 kPa. What is the angle of internal friction?","options":[{"key":"a","text":"30 degree"},{"key":"b","text":"60 degree"},{"key":"c","text":"45 degree"},{"key":"d","text":"90 degree"}],"answer":"a","explanation":"With \\(\\sigma_3 = 50\\) and \\(\\sigma_1 = 150\\) kPa, \\[\\begin{aligned} \\sin\\phi &amp;= \\dfrac{\\sigma_1 - \\sigma_3}{\\sigma_1 + \\sigma_3} \\\\ &amp;= \\dfrac{100}{200} = 0.5 \\end{aligned}\\] and \\(\\phi = 30^\\circ\\). The paper prints a cell pressure of 150 kPa, which would give about \\(14.5^\\circ\\). The key's working uses 50 kPa, so that value is shown here.","marks":2,"source":{"kind":"past","set":10,"question":70,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q70 · 2 marks"},"topic":"ACiE0203"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-10-011","src":"PAST-10-011","text":"The maximum density of water is at ……. degree Celsius.","options":[{"key":"a","text":"0 degree"},{"key":"b","text":"4 degree"},{"key":"c","text":"100 degree"},{"key":"d","text":"−4 degree"}],"answer":"b","explanation":"Water is densest (about 1000 kg per m<sup>3</sup>) at about \\(4^\\circ\\text{C}\\). It expands on cooling below \\(4^\\circ\\text{C}\\), which is why ice floats.","marks":1,"source":{"kind":"past","set":10,"question":11,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q11 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-10-020","src":"PAST-10-020","text":"The condition for supercritical flow is","options":[{"key":"a","text":"\\(\\mathrm{Fr} \\lt 0.67\\)"},{"key":"b","text":"\\(\\mathrm{Fr} \\lt 1\\)"},{"key":"c","text":"\\(\\mathrm{Fr} = 1\\)"},{"key":"d","text":"\\(\\mathrm{Fr} \\gt 1\\)"}],"answer":"d","explanation":"Supercritical (rapid, shooting) flow has \\[\\text{Fr} = \\dfrac{V}{\\sqrt{gD}} \\gt 1\\] \\(\\text{Fr} \\lt 1\\) is subcritical and \\(\\text{Fr} = 1\\) is critical.","marks":1,"source":{"kind":"past","set":10,"question":20,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q20 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-10-024","src":"PAST-10-024","text":"The ordinate of a unit hydrograph is obtained by dividing the ordinate of the DRH by","options":[{"key":"a","text":"effective run off depth"},{"key":"b","text":"area of catchment"},{"key":"c","text":"base flow"},{"key":"d","text":"none of these"}],"answer":"a","explanation":"The UH ordinate is the DRH ordinate divided by the effective rainfall (runoff) depth in cm, which scales the hydrograph to 1 cm of runoff.","marks":1,"source":{"kind":"past","set":10,"question":24,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q24 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-10-025","src":"PAST-10-025","text":"Which of the following is right?","options":[{"key":"a","text":"\\(P_\\mathrm{gauge} = P_\\mathrm{atm} - P_\\mathrm{abs}\\)"},{"key":"b","text":"\\(P_\\mathrm{abs} = P_\\mathrm{atm} - P_\\mathrm{gauge}\\)"},{"key":"c","text":"\\(P_\\mathrm{atm} = P_\\mathrm{abs} + P_\\mathrm{gauge}\\)"},{"key":"d","text":"\\(P_\\mathrm{abs} = P_\\mathrm{atm} + P_\\mathrm{gauge}\\)"}],"answer":"d","explanation":"Absolute pressure is atmospheric plus gauge pressure: \\[P_{abs} = P_{atm} + P_{gauge}\\] Vacuum pressure is \\(P_{atm} - P_{abs}\\).","marks":1,"source":{"kind":"past","set":10,"question":25,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q25 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-10-030","src":"PAST-10-030","text":"In open channel flow, the alternate depths are","options":[{"key":"a","text":"those which have the same specific force"},{"key":"b","text":"those which occur at the same specific energy"},{"key":"c","text":"at the same velocity points"},{"key":"d","text":"at critical depth"}],"answer":"b","explanation":"For a given discharge and specific energy above the minimum, two depths are possible, one subcritical and one supercritical. These are the alternate depths. Equal specific force defines the sequent (conjugate) depths.","marks":1,"source":{"kind":"past","set":10,"question":30,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q30 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-10-053","src":"PAST-10-053","text":"For a vertical stationary plate, the jet after striking moves","options":[{"key":"a","text":"in opposite direction"},{"key":"b","text":"along the plate"},{"key":"c","text":"normal to the surface of plate"},{"key":"d","text":"depends on material of plate"}],"answer":"b","explanation":"A jet striking a flat plate normally is deflected through 90° and spreads out along the plate surface, losing all its normal momentum.","marks":1,"source":{"kind":"past","set":10,"question":53,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q53 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-10-056","src":"PAST-10-056","text":"A pitot tube is used to measure","options":[{"key":"a","text":"pressure"},{"key":"b","text":"difference in pressure"},{"key":"c","text":"velocity of flow"},{"key":"d","text":"none of these"}],"answer":"c","explanation":"A pitot tube senses the stagnation pressure. The rise above the static level equals \\(\\dfrac{V^2}{2g}\\), so it measures the point velocity: \\[V = C\\sqrt{2gh}\\]","marks":1,"source":{"kind":"past","set":10,"question":56,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q56 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-10-059","src":"PAST-10-059","text":"Precipitation caused by the lifting of an air mass due to a pressure difference is called","options":[{"key":"a","text":"cyclonic precipitation"},{"key":"b","text":"convective precipitation"},{"key":"c","text":"orographic precipitation"},{"key":"d","text":"none of these"}],"answer":"a","explanation":"Cyclonic (frontal) precipitation results when air converges into a low-pressure area and is lifted. Convective precipitation comes from heating, orographic from mountain barriers.","marks":1,"source":{"kind":"past","set":10,"question":59,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q59 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-10-072","src":"PAST-10-072","text":"What is the incompressibility condition in the Navier–Stokes equation?","options":[{"key":"a","text":"\\(\\nabla\\cdot\\mathbf{u} = 1\\)"},{"key":"b","text":"\\(\\nabla\\cdot\\mathbf{u} \\gt 0\\)"},{"key":"c","text":"\\(\\nabla\\cdot\\mathbf{u} \\lt 0\\)"},{"key":"d","text":"\\(\\nabla\\cdot\\mathbf{u} = 0\\)"}],"answer":"d","explanation":"For incompressible flow the continuity equation reduces to zero divergence of velocity: \\[\\nabla \\cdot \\mathbf{u} = \\dfrac{\\partial u}{\\partial x} + \\dfrac{\\partial v}{\\partial y} + \\dfrac{\\partial w}{\\partial z} = 0\\]","marks":2,"source":{"kind":"past","set":10,"question":72,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q72 · 2 marks"},"topic":"ACiE0303"},{"id":"PAST-10-073","src":"PAST-10-073","text":"The area of a channel section is 8 m<sup>2</sup> and the wetted perimeter is 8 m. Calculate the value of the bed slope of the channel if the discharge is 33.33 m<sup>3</sup>/s and Manning's coefficient is 0.012.","options":[{"key":"a","text":"1 in 300"},{"key":"b","text":"1 in 400"},{"key":"c","text":"1 in 500"},{"key":"d","text":"1 in 600"}],"answer":"b","explanation":"Here \\(R = \\dfrac{8}{8} = 1\\) m and \\(V = \\dfrac{33.33}{8} = 4.17\\) m per s. Then \\[\\begin{aligned} S &amp;= \\left(\\dfrac{nV}{R^{2{/}3}}\\right)^2 \\\\ &amp;= (0.012 \\times 4.17)^2 \\\\ &amp;\\approx 0.0025 = 1\\ \\text{in}\\ 400 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":10,"question":73,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q73 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-10-077","src":"PAST-10-077","text":"Two identical pipes of length L, diameter D and friction f are connected in parallel between two points. The length of a single pipe of diameter D and the same friction f, equivalent to the above pair, is","options":[{"key":"a","text":"2L"},{"key":"b","text":"L/2"},{"key":"c","text":"4L"},{"key":"d","text":"L/4"}],"answer":"d","explanation":"Each parallel pipe carries \\(\\dfrac{Q}{2}\\) with the same head loss. For one pipe carrying \\(Q\\) with that loss, \\[L_eQ^2 = L\\left(\\dfrac{Q}{2}\\right)^2\\] so \\(L_e = \\dfrac{L}{4}\\).","marks":2,"source":{"kind":"past","set":10,"question":77,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q77 · 2 marks"},"topic":"ACiE0304"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-10-007","src":"PAST-10-007","text":"The relation of \\(E\\), \\(G\\) and \\(\\mu\\) is","options":[{"key":"a","text":"\\(\\mu = \\dfrac{E}{G} - 1\\)"},{"key":"b","text":"\\(\\mu = \\dfrac{E}{2G} - 1\\)"},{"key":"c","text":"\\(\\mu = \\dfrac{E}{2G} - 2\\)"},{"key":"d","text":"\\(\\mu = \\dfrac{E}{2G} - 0.5\\)"}],"answer":"b","explanation":"Since \\(E = 2G(1 + \\mu)\\), \\[\\mu = \\dfrac{E}{2G} - 1\\]","marks":1,"source":{"kind":"past","set":10,"question":7,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q7 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-10-008","src":"PAST-10-008","text":"Which of the following is an indeterminate structure?","options":[{"key":"a","text":"Three hinge arches"},{"key":"b","text":"Two hinge arches"},{"key":"c","text":"Simple supported beam"},{"key":"d","text":"Cantilever beam"}],"answer":"b","explanation":"A two-hinged arch has four reaction components and only three equilibrium equations, so it is indeterminate to the first degree. The third hinge makes a three-hinged arch determinate.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-008-two-and-three-hinged-arch-determinacy.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Reactions of two-hinged and three-hinged arches'><img src='assets/civil-past-solutions/past-10-008-two-and-three-hinged-arch-determinacy.svg' width='720' height='420' loading='lazy' decoding='async' alt='Both arches have four reaction components, H and V at each support. The three-hinged arch adds the equation M = 0 at the crown hinge and is determinate; the two-hinged arch has only the three equilibrium equations, so it is indeterminate to the first degree.'></a><figcaption>Reactions of two-hinged and three-hinged arches</figcaption></figure>","marks":1,"source":{"kind":"past","set":10,"question":8,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q8 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-10-013","src":"PAST-10-013","text":"One end of a column is kept free and the other end fixed. The ratio of L<sub>eff</sub> to L is","options":[{"key":"a","text":"1/3"},{"key":"b","text":"1/2"},{"key":"c","text":"2"},{"key":"d","text":"1"}],"answer":"c","explanation":"A cantilever column (fixed-free) buckles like half of a pin-ended column of twice its length, so \\[l_e = 2L\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-013-fixed-free-effective-length.svg' target='_blank' rel='noopener noreferrer' aria-label='Open A fixed-free column buckles like half of a pin-ended column of length 2L'><img src='assets/civil-past-solutions/past-10-013-fixed-free-effective-length.svg' width='720' height='420' loading='lazy' decoding='async' alt='A column fixed at the base and free at the top bends into a quarter wave. Reflecting it about the base gives the half wave of a pin-ended column of length 2L, so the effective length is 2L and Leff/L = 2.'></a><figcaption>A fixed-free column buckles like half of a pin-ended column of length 2L</figcaption></figure>","marks":1,"source":{"kind":"past","set":10,"question":13,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q13 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-10-031","src":"PAST-10-031","text":"The X and Y axes of Mohr's circle represent","options":[{"key":"a","text":"principal shear stress and principal normal stress"},{"key":"b","text":"shear stress and normal stress"},{"key":"c","text":"principal normal stress and principal shear stress"},{"key":"d","text":"normal stress and shear stress"}],"answer":"d","explanation":"Mohr's circle is plotted with normal stress σ on the horizontal (x) axis and shear stress τ on the vertical (y) axis.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-031-axes-of-mohr-circle.svg' target='_blank' rel='noopener noreferrer' aria-label='Open The axes of Mohr&#39;s circle'><img src='assets/civil-past-solutions/past-10-031-axes-of-mohr-circle.svg' width='720' height='420' loading='lazy' decoding='async' alt='Mohr&#39;s circle is drawn with normal stress σ along the horizontal axis and shear stress τ along the vertical axis. The face stresses (σx, τxy) and (σy, -τxy) are the ends of a diameter, with the centre at the average normal stress.'></a><figcaption>The axes of Mohr&#39;s circle</figcaption></figure>","marks":1,"source":{"kind":"past","set":10,"question":31,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q31 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-10-036","src":"PAST-10-036","text":"The simultaneous equations of the slope deflection method can be solved by iteration in","options":[{"key":"a","text":"conjugate beam method"},{"key":"b","text":"consistent deformation method"},{"key":"c","text":"moment distribution method"},{"key":"d","text":"Williot Mohr method"}],"answer":"c","explanation":"Hardy Cross's moment distribution method is an iterative (successive-approximation) solution of the slope-deflection equations, distributing and carrying over moments until balance.","marks":1,"source":{"kind":"past","set":10,"question":36,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q36 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-10-039","src":"PAST-10-039","text":"The radial shear in a two hinged arch, where the tangent to the arch makes an angle \\(\\theta\\) with the horizontal, is","options":[{"key":"a","text":"\\(H\\cos\\theta + V\\sin\\theta\\)"},{"key":"b","text":"\\(V\\cos\\theta + H\\sin\\theta\\)"},{"key":"c","text":"\\(V\\cos\\theta - H\\sin\\theta\\)"},{"key":"d","text":"\\(H\\cos\\theta - V\\sin\\theta\\)"}],"answer":"c","explanation":"Resolving the horizontal thrust \\(H\\) and the vertical shear \\(V\\) normal to the arch axis gives the radial shear \\[S = V\\cos\\theta - H\\sin\\theta\\] The normal thrust is \\(N = H\\cos\\theta + V\\sin\\theta\\).<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-039-resolving-h-and-v-at-an-arch-section.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Resolving H and V at an arch section into thrust and radial shear'><img src='assets/civil-past-solutions/past-10-039-resolving-h-and-v-at-an-arch-section.svg' width='720' height='420' loading='lazy' decoding='async' alt='At a section where the arch tangent makes θ with the horizontal, the components of H and V along the tangent add to the normal thrust N = H cosθ + V sinθ, and the components along the radius give the radial shear S = V cosθ - H sinθ.'></a><figcaption>Resolving H and V at an arch section into thrust and radial shear</figcaption></figure>","marks":1,"source":{"kind":"past","set":10,"question":39,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q39 · 1 mark"},"topic":"ACiE0405"},{"id":"PAST-10-050","src":"PAST-10-050","text":"A beam is said to be continuous if","options":[{"key":"a","text":"fixed at both ends"},{"key":"b","text":"fixed at one end and free at the other end"},{"key":"c","text":"supported on more than two supports"},{"key":"d","text":"extending beyond the support"}],"answer":"c","explanation":"A continuous beam runs over three or more supports. Fixed–fixed and propped beams are single-span, and a beam projecting beyond its support is an overhanging beam.","marks":1,"source":{"kind":"past","set":10,"question":50,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q50 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-10-060","src":"PAST-10-060","text":"Principal planes are subjected to","options":[{"key":"a","text":"normal stresses only"},{"key":"b","text":"tangential stresses only"},{"key":"c","text":"normal stresses as well as tangential stresses"},{"key":"d","text":"none of these"}],"answer":"a","explanation":"Principal planes carry only normal (principal) stresses. The shear stress on them is zero.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-060-principal-planes-normal-stress-only.svg' target='_blank' rel='noopener noreferrer' aria-label='Open On principal planes only normal stresses act'><img src='assets/civil-past-solutions/past-10-060-principal-planes-normal-stress-only.svg' width='720' height='420' loading='lazy' decoding='async' alt='Rotating a stressed element through θp, with tan 2θp = 2τxy/(σx - σy), removes all the shear from its faces. The principal planes then carry only the normal principal stresses σ1 and σ2.'></a><figcaption>On principal planes only normal stresses act</figcaption></figure>","marks":1,"source":{"kind":"past","set":10,"question":60,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q60 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-10-061","src":"PAST-10-061","text":"When a uniformly distributed load (UDL) longer than the girder is moved from left to right, the bending moment (BM) is maximum","options":[{"key":"a","text":"when the UDL is to the left of the midpoint of the beam"},{"key":"b","text":"when the UDL is at the middle of the beam"},{"key":"c","text":"when the UDL crosses the midpoint of the beam"},{"key":"d","text":"when the UDL covers the entire beam"}],"answer":"d","explanation":"A UDL longer than the span gives the greatest moment at every section when it covers the whole span, since every influence-line ordinate is positive. The midspan moment is then \\(\\dfrac{wL^2}{8}\\).<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-061-long-udl-covers-the-span.svg' target='_blank' rel='noopener noreferrer' aria-label='Open A uniform load longer than the span gives the greatest moment when it covers the span'><img src='assets/civil-past-solutions/past-10-061-long-udl-covers-the-span.svg' width='720' height='420' loading='lazy' decoding='async' alt='Every ordinate of the moment influence line of a simple beam is positive, so the moment at any section is largest when the whole span is loaded. The mid-span moment is then wL squared/8.'></a><figcaption>A uniform load longer than the span gives the greatest moment when it covers the span</figcaption></figure>","marks":2,"source":{"kind":"past","set":10,"question":61,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q61 · 2 marks"},"topic":"ACiE0404"},{"id":"PAST-10-062","src":"PAST-10-062","text":"A body is subjected to a direct tensile stress of 300 MPa in one plane accompanied by a simple shear stress of 200 MPa. The maximum normal stress on the plane will be","options":[{"key":"a","text":"300 MPa"},{"key":"b","text":"400 MPa"},{"key":"c","text":"350 MPa"},{"key":"d","text":"450 MPa"}],"answer":"b","explanation":"The major principal stress is \\[\\sigma_1 = \\dfrac{\\sigma}{2} + \\sqrt{\\left(\\dfrac{\\sigma}{2}\\right)^2 + \\tau^2}\\] \\[\\begin{aligned} &amp;= 150 + \\sqrt{150^2 + 200^2} \\\\ &amp;= 150 + 250 = 400\\ \\text{MPa} \\end{aligned}\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-062-mohr-circle-300-and-200.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Maximum normal stress for 300 MPa tension with 200 MPa shear'><img src='assets/civil-past-solutions/past-10-062-mohr-circle-300-and-200.svg' width='720' height='420' loading='lazy' decoding='async' alt='Mohr&#39;s circle for σ = 300 MPa and τ = 200 MPa has its centre at 150 MPa and radius root(150 squared + 200 squared) = 250 MPa. The major principal stress is 150 + 250 = 400 MPa.'></a><figcaption>Maximum normal stress for 300 MPa tension with 200 MPa shear</figcaption></figure>","marks":2,"source":{"kind":"past","set":10,"question":62,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q62 · 2 marks"},"topic":"ACiE0402"},{"id":"PAST-10-074","src":"PAST-10-074","text":"For a fixed-end beam of length \\(L\\) and central point load \\(W\\), what will be the value of \\(W\\) at collapse?","options":[{"key":"a","text":"\\(\\dfrac{6M_p}{L}\\)"},{"key":"b","text":"\\(\\dfrac{10M_p}{L}\\)"},{"key":"c","text":"\\(\\dfrac{9M_p}{L}\\)"},{"key":"d","text":"\\(\\dfrac{8M_p}{L}\\)"}],"answer":"d","explanation":"Hinges form at both ends and at midspan. Virtual work gives \\[W\\dfrac{L\\theta}{2} = M_p(\\theta + 2\\theta + \\theta)\\] so \\[W_c = \\dfrac{8M_p}{L}\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-074-fixed-beam-collapse-mechanism.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Collapse mechanism of a fixed beam under a central load'><img src='assets/civil-past-solutions/past-10-074-fixed-beam-collapse-mechanism.svg' width='720' height='420' loading='lazy' decoding='async' alt='Plastic hinges form at both fixed ends and under the load. If the end hinges rotate θ the centre hinge rotates 2θ and the load moves Lθ/2, so W(Lθ/2) = Mp(θ + 2θ + θ) and the collapse load is 8Mp/L.'></a><figcaption>Collapse mechanism of a fixed beam under a central load</figcaption></figure>","marks":2,"source":{"kind":"past","set":10,"question":74,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q74 · 2 marks"},"topic":"ACiE0406"}]},{"name":"Design of Structures","questions":[{"id":"PAST-10-004","src":"PAST-10-004","text":"Web crippling in a steel beam occurs due to","options":[{"key":"a","text":"Excessive bending moment"},{"key":"b","text":"Failure of web under concentrated load"},{"key":"c","text":"Secondary bending moment"},{"key":"d","text":"Column action of compression flange"}],"answer":"b","explanation":"Web crippling is local yielding of the web at the root of the flange under concentrated loads or reactions. Bearing stiffeners are provided to prevent it.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-004-web-crippling-under-a-load.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Web crippling under a concentrated load'><img src='assets/civil-past-solutions/past-10-004-web-crippling-under-a-load.svg' width='720' height='420' loading='lazy' decoding='async' alt='A concentrated load or reaction spreads through the flange and root fillet onto a short length of the thin web. If the bearing stress there is too high the web yields locally at the root of the flange, which is web crippling; bearing stiffeners prevent it.'></a><figcaption>Web crippling under a concentrated load</figcaption></figure>","marks":1,"source":{"kind":"past","set":10,"question":4,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q4 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-10-037","src":"PAST-10-037","text":"The middle 1/3 rule is used to avoid","options":[{"key":"a","text":"shear"},{"key":"b","text":"compression"},{"key":"c","text":"sliding"},{"key":"d","text":"tension"}],"answer":"d","explanation":"Keeping the resultant within the middle third of a masonry or dam base (e ≤ b/6) ensures no tension anywhere at the base.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-037-middle-third-and-base-pressure.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Base pressure for a resultant inside, on and outside the middle third'><img src='assets/civil-past-solutions/past-10-037-middle-third-and-base-pressure.svg' width='720' height='420' loading='lazy' decoding='async' alt='For a resultant P at eccentricity e the base pressure is (P/b)(1 ± 6e/b). Inside the middle third (e less than b/6) the whole base is in compression; at e = b/6 the pressure falls to zero at one edge; beyond it that edge goes into tension.'></a><figcaption>Base pressure for a resultant inside, on and outside the middle third</figcaption></figure>","marks":1,"source":{"kind":"past","set":10,"question":37,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q37 · 1 mark"},"topic":"ACiE0506"},{"id":"PAST-10-038","src":"PAST-10-038","text":"The maximum compressive strain in concrete in axial compression is taken as","options":[{"key":"a","text":"0.002"},{"key":"b","text":"0.0200"},{"key":"c","text":"0.0035"},{"key":"d","text":"0.0050"}],"answer":"a","explanation":"IS 456 limits the strain in concrete under pure axial compression to 0.002. Under flexure the limit is 0.0035 at the extreme fibre.","marks":1,"source":{"kind":"past","set":10,"question":38,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q38 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-10-049","src":"PAST-10-049","text":"Steel is preferred over other materials in reinforcement because","options":[{"key":"a","text":"it is easily available"},{"key":"b","text":"it is cheapest and good in strength"},{"key":"c","text":"the coefficient of thermal expansion of steel and concrete is almost same"},{"key":"d","text":"it forms a good bond"}],"answer":"c","explanation":"Steel and concrete have almost equal thermal expansion coefficients (about \\(10\\text{-}12 \\times 10^{-6}\\) per \\(^\\circ\\text{C}\\)), so temperature changes do not break their bond. This makes reinforced concrete work.","marks":1,"source":{"kind":"past","set":10,"question":49,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q49 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-10-066","src":"PAST-10-066","text":"If 50 kg of fine aggregates and 100 kg of coarse aggregates are mixed in a concrete whose water cement ratio is 0.6, the weight of water required for a harsh mix is","options":[{"key":"a","text":"8 kg"},{"key":"b","text":"10 kg"},{"key":"c","text":"12 kg"},{"key":"d","text":"14 kg"}],"answer":"c","explanation":"A harsh mix at a water-cement ratio of 0.6 has an aggregate-cement ratio of about 7.5 by weight, so \\[\\text{cement} \\approx \\dfrac{150}{7.5} = 20\\ \\text{kg}\\] \\[\\text{water} = 0.6 \\times 20 = 12\\ \\text{kg}\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-066-batch-weights-of-a-harsh-mix.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Batch weights for a harsh mix at a water-cement ratio of 0.6'><img src='assets/civil-past-solutions/past-10-066-batch-weights-of-a-harsh-mix.svg' width='720' height='420' loading='lazy' decoding='async' alt='The batch has 50 + 100 = 150 kg of aggregate. A harsh mix at w/c 0.6 has an aggregate-cement ratio of about 7.5, so the cement is 150/7.5 = 20 kg and the water is 0.6 x 20 = 12 kg.'></a><figcaption>Batch weights for a harsh mix at a water-cement ratio of 0.6</figcaption></figure>","marks":2,"source":{"kind":"past","set":10,"question":66,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q66 · 2 marks"},"topic":"ACiE0502"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-10-003","src":"PAST-10-003","text":"For a given discharge, the efficiency of a sedimentation tank can be increased by","options":[{"key":"a","text":"Increasing depth of basin"},{"key":"b","text":"increasing area of basin"},{"key":"c","text":"decreasing depth"},{"key":"d","text":"Decreasing area of basin"}],"answer":"b","explanation":"Removal efficiency depends on the surface overflow rate Q/A, not the depth. A larger plan area lowers the overflow rate, so finer particles settle.","marks":1,"source":{"kind":"past","set":10,"question":3,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q3 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-10-016","src":"PAST-10-016","text":"The permissible pH value for public water supply ranges between","options":[{"key":"a","text":"4.5 to 5.5"},{"key":"b","text":"6.5 to 8.5"},{"key":"c","text":"5.5 to 6.5"},{"key":"d","text":"8.5 to 10.5"}],"answer":"b","explanation":"Drinking water standards (NDWQS, WHO, IS 10500) specify a pH of 6.5–8.5.","marks":1,"source":{"kind":"past","set":10,"question":16,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q16 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-10-017","src":"PAST-10-017","text":"The minimum size of sewer is","options":[{"key":"a","text":"30 m"},{"key":"b","text":"15 mm"},{"key":"c","text":"30 cm"},{"key":"d","text":"15 cm"}],"answer":"d","explanation":"Public sewers are generally at least 150 mm (15 cm) in diameter to avoid choking. House drains may be 100 mm.","marks":1,"source":{"kind":"past","set":10,"question":17,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q17 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-10-043","src":"PAST-10-043","text":"The exhausted permutit is generally regenerated by percolating through it a solution of","options":[{"key":"a","text":"sodium chloride"},{"key":"b","text":"calcium chloride"},{"key":"c","text":"magnesium chloride"},{"key":"d","text":"barium chloride"}],"answer":"a","explanation":"Permutit (sodium zeolite) exhausted by Ca and Mg ions is regenerated with 5–10% brine (NaCl), which restores the sodium zeolite.","marks":1,"source":{"kind":"past","set":10,"question":43,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q43 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-10-044","src":"PAST-10-044","text":"A vacuum filter is most suitable for the","options":[{"key":"a","text":"removal of fines from liquid"},{"key":"b","text":"liquids having high vapour pressure"},{"key":"c","text":"liquids of very high viscosity"},{"key":"d","text":"none of these"}],"answer":"d","explanation":"Vacuum filters are used mainly to dewater sludges. Fines clog the medium, high-vapour-pressure liquids flash under vacuum, and very viscous liquids need pressure filters, so none of the listed uses suits them.","marks":1,"source":{"kind":"past","set":10,"question":44,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q44 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-10-054","src":"PAST-10-054","text":"Which distribution system is used in an irregularly developed old city?","options":[{"key":"a","text":"Radial system"},{"key":"b","text":"Gridiron system"},{"key":"c","text":"Ring system"},{"key":"d","text":"Dead end system"}],"answer":"d","explanation":"Old towns with irregular, unplanned streets are served by the dead-end (tree) system, since mains simply follow the existing lanes. Planned towns use gridiron or ring systems.","marks":1,"source":{"kind":"past","set":10,"question":54,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q54 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-10-057","src":"PAST-10-057","text":"The removal of oil and grease from sewage is known as","options":[{"key":"a","text":"screening"},{"key":"b","text":"skimming"},{"key":"c","text":"filtration"},{"key":"d","text":"none of these"}],"answer":"b","explanation":"Oil and grease float to the surface in skimming tanks (grease traps) and are skimmed off. Screens remove floating solids and grit chambers remove sand.","marks":1,"source":{"kind":"past","set":10,"question":57,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q57 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-10-064","src":"PAST-10-064","text":"If the discharge of a pump is 0.16 cumecs, the economic diameter of the pipe is","options":[{"key":"a","text":"68.8 cm"},{"key":"b","text":"1.12 m"},{"key":"c","text":"0.976 m"},{"key":"d","text":"0.480 m"}],"answer":"d","explanation":"By Lea's formula, \\(D \\approx 0.97\\) to \\(1.22\\sqrt{Q}\\). With the upper coefficient, \\[D = 1.22 \\times \\sqrt{0.16} \\approx 0.49\\ \\text{m}\\] so about 0.48 m.","marks":2,"source":{"kind":"past","set":10,"question":64,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q64 · 2 marks"},"topic":"ACiE0602"},{"id":"PAST-10-078","src":"PAST-10-078","text":"In a treatment plant, if BOD decreases from 300 mg/l to 30 mg/l, then the efficiency of the treatment plant is","options":[{"key":"a","text":"100%"},{"key":"b","text":"95%"},{"key":"c","text":"90%"},{"key":"d","text":"85%"}],"answer":"c","explanation":"The efficiency is \\[\\eta = \\dfrac{300 - 30}{300} \\times 100 = 90\\%\\]","marks":2,"source":{"kind":"past","set":10,"question":78,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q78 · 2 marks"},"topic":"ACiE0605"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-10-019","src":"PAST-10-019","text":"A canal fall is provided if","options":[{"key":"a","text":"ground slope exceeds designed bed slope"},{"key":"b","text":"design bed slope exceeds ground slope"},{"key":"c","text":"ground slope is same as designed bed slope"},{"key":"d","text":"none of these"}],"answer":"a","explanation":"Where the ground falls more steeply than the permissible canal bed slope, the canal would be in heavy filling. A fall drops the bed in steps instead.","marks":1,"source":{"kind":"past","set":10,"question":19,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q19 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-10-026","src":"PAST-10-026","text":"Which is not a component of river training works?","options":[{"key":"a","text":"Spur"},{"key":"b","text":"Catchment area"},{"key":"c","text":"Marginal bund"},{"key":"d","text":"Launching apron"}],"answer":"b","explanation":"Spurs, launching aprons, marginal bunds and guide banks are river training structures. The catchment area is the drainage basin, not a structure.","marks":1,"source":{"kind":"past","set":10,"question":26,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q26 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-10-028","src":"PAST-10-028","text":"The Lacey silt factor for 0.35 mm diameter particles is","options":[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"0.5"},{"key":"d","text":"0.67"}],"answer":"a","explanation":"Lacey's silt factor is \\[f = 1.76\\sqrt{0.35} \\approx 1.04 \\approx 1.0\\] (standard silt).","marks":1,"source":{"kind":"past","set":10,"question":28,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q28 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-10-033","src":"PAST-10-033","text":"Which crop has the highest water use efficiency?","options":[{"key":"a","text":"Wheat"},{"key":"b","text":"Rice"},{"key":"c","text":"Millet"},{"key":"d","text":"all"}],"answer":"c","explanation":"Millets are drought-hardy C<sub>4</sub> crops that produce more grain per unit of water than wheat and far more than paddy, which has the lowest water use efficiency.","marks":1,"source":{"kind":"past","set":10,"question":33,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q33 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-10-045","src":"PAST-10-045","text":"The irrigation requirement depends on which of the following parameters?","options":[{"key":"a","text":"Crop"},{"key":"b","text":"Soil"},{"key":"c","text":"Climate"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"Crop water needs depend on the crop and its stage, the climate (evapotranspiration, rainfall) and the soil (infiltration, holding capacity, losses). All three govern the irrigation requirement.","marks":1,"source":{"kind":"past","set":10,"question":45,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q45 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-10-058","src":"PAST-10-058","text":"In a Sarda type fall, the rectangular crest may be used for discharges up to","options":[{"key":"a","text":"6 cumecs"},{"key":"b","text":"10 cumecs"},{"key":"c","text":"14 cumecs"},{"key":"d","text":"20 cumecs"}],"answer":"c","explanation":"Sarda falls use a rectangular crest for discharges up to about 14 cumecs and a trapezoidal crest for larger discharges.","marks":1,"source":{"kind":"past","set":10,"question":58,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q58 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-10-068","src":"PAST-10-068","text":"Determine the volume of water stored in unit area if the unit weight of water is 9.8 kN/m<sup>3</sup>, the dry unit weight of soil is 17 kN/m<sup>3</sup>, the field capacity (F) is 2.35 and the depth of the root zone of the plant is 9 m.","options":[{"key":"a","text":"36.69 m<sup>3</sup>"},{"key":"b","text":"36 m<sup>3</sup>"},{"key":"c","text":"36.12 m<sup>3</sup>"},{"key":"d","text":"36.25 m<sup>3</sup>"}],"answer":"a","explanation":"The water held per unit area is \\[\\begin{aligned} &amp;\\dfrac{\\gamma_d}{\\gamma_w} \\times F \\times d \\\\ &amp;= \\dfrac{17}{9.8} \\times 2.35 \\times 9 \\\\ &amp;\\approx 36.69\\ \\text{m}^3 \\end{aligned}\\] (the paper's field-capacity value is used as given).","marks":2,"source":{"kind":"past","set":10,"question":68,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q68 · 2 marks"},"topic":"ACiE0701"}]},{"name":"Hydropower","questions":[{"id":"PAST-10-021","src":"PAST-10-021","text":"Reversible turbines are used in","options":[{"key":"a","text":"Pumped storage"},{"key":"b","text":"Reservoir plant"},{"key":"c","text":"ROR plant"},{"key":"d","text":"Tidal plant"}],"answer":"a","explanation":"Pumped-storage plants use reversible pump-turbines: they pump water uphill with surplus off-peak power and generate at peak.","marks":1,"source":{"kind":"past","set":10,"question":21,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q21 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-10-041","src":"PAST-10-041","text":"The power generated under a unit head (for a unit-size turbine) is","options":[{"key":"a","text":"Horse power"},{"key":"b","text":"Unit speed"},{"key":"c","text":"Specific speed"},{"key":"d","text":"Unit power"}],"answer":"d","explanation":"Unit power \\[P_u = \\dfrac{P}{H^{3{/}2}}\\] is the power the turbine would develop under a unit head. Unit speed and unit discharge are defined similarly.","marks":1,"source":{"kind":"past","set":10,"question":41,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q41 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-10-047","src":"PAST-10-047","text":"What is the function of a surge tank?","options":[{"key":"a","text":"It causes water hammer"},{"key":"b","text":"Produces surge in the pipeline"},{"key":"c","text":"Relieves water hammer"},{"key":"d","text":"Supplies water at constant pressure"}],"answer":"c","explanation":"A surge tank relieves water-hammer pressures by providing a free surface that absorbs flow changes when the turbine gates close or open.","marks":1,"source":{"kind":"past","set":10,"question":47,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q47 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-10-048","src":"PAST-10-048","text":"What should be done to avoid the friction (sliding) failure of a dam?","options":[{"key":"a","text":"Decrease the base width"},{"key":"b","text":"Provide anchorage at the bottom"},{"key":"c","text":"Provide anchorage at the top"},{"key":"d","text":"Increase the base width"}],"answer":"b","explanation":"Sliding along the base is resisted by friction and shear, and anchoring or keying the base into the foundation rock (anchor bars, shear keys, stepped foundation) adds direct shear resistance, as the key states. Widening the base also helps by adding weight.","marks":1,"source":{"kind":"past","set":10,"question":48,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q48 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-10-051","src":"PAST-10-051","text":"The bottom portion of a concrete or masonry gravity dam is usually stepped in order to","options":[{"key":"a","text":"increase overturning resistance of the dam"},{"key":"b","text":"increase the shear strength"},{"key":"c","text":"decrease the shear strength"},{"key":"d","text":"increase the frictional resistance"}],"answer":"b","explanation":"Stepping (benching) the foundation keys the dam into the rock. The shear strength of the rock must then be overcome for sliding, which raises the shear-friction resistance.","marks":1,"source":{"kind":"past","set":10,"question":51,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q51 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-10-063","src":"PAST-10-063","text":"Which of the following is correct?","options":[{"key":"a","text":"Francis is impulse turbine"},{"key":"b","text":"Pelton is reaction turbine"},{"key":"c","text":"Kaplan is impulse turbine"},{"key":"d","text":"Pelton is impulse turbine"}],"answer":"d","explanation":"The Pelton wheel is an impulse turbine. Francis and Kaplan are reaction turbines.","marks":2,"source":{"kind":"past","set":10,"question":63,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q63 · 2 marks"},"topic":"ACiE0806"},{"id":"PAST-10-069","src":"PAST-10-069","text":"If 20% of the reservoir capacity is earmarked for dead storage in a storage reservoir of 30 M.cum and the average annual silt deposition in the reservoir is 0.1 M.cum, then the useful life of the reservoir will start reducing after","options":[{"key":"a","text":"30 years"},{"key":"b","text":"90 years"},{"key":"c","text":"150 years"},{"key":"d","text":"60 years"}],"answer":"d","explanation":"The dead storage is \\(0.2 \\times 30 = 6\\) M.cum. At 0.1 M.cum of silt per year it fills in \\[\\dfrac{6}{0.1} = 60\\ \\text{years}\\] after which sediment starts eating into the live storage.","marks":2,"source":{"kind":"past","set":10,"question":69,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q69 · 2 marks"},"topic":"ACiE0803"},{"id":"PAST-10-071","src":"PAST-10-071","text":"Identify the correct statement about hydropower.","options":[{"key":"a","text":"Hydropower stations are generally labour oriented"},{"key":"b","text":"The gestation period for hydropower plant is usually small"},{"key":"c","text":"The hydro generators give high efficiency over a wide range of load"},{"key":"d","text":"In a hydropower scheme, the firm power is usually high as compared to tidal power"}],"answer":"c","explanation":"Hydro turbine-generators keep high efficiency (about 90%) over a wide range of loads and respond quickly. Hydro plants need few staff and have long gestation periods.","marks":2,"source":{"kind":"past","set":10,"question":71,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q71 · 2 marks"},"topic":"ACiE0801"}]},{"name":"Transportation","questions":[{"id":"PAST-10-009","src":"PAST-10-009","text":"Bitumen content is determined by which test?","options":[{"key":"a","text":"Vee-bee test"},{"key":"b","text":"Penetration test"},{"key":"c","text":"Marshall test"},{"key":"d","text":"Ductility test"}],"answer":"c","explanation":"The optimum bitumen content of a bituminous mix is found by Marshall mix design, from the stability, flow, density and voids at trial binder contents.","marks":1,"source":{"kind":"past","set":10,"question":9,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q9 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-10-012","src":"PAST-10-012","text":"The ROW for a feeder road is","options":[{"key":"a","text":"30 m"},{"key":"b","text":"50 m"},{"key":"c","text":"20 m"},{"key":"d","text":"45 m"}],"answer":"a","explanation":"The Nepal Road Standard sets the right of way at 50 m for national highways and 30 m for feeder roads (15 m each side of the centre line).","marks":1,"source":{"kind":"past","set":10,"question":12,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q12 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-10-042","src":"PAST-10-042","text":"The length (of road) visible to a driver at any instant of time is called","options":[{"key":"a","text":"overtaking sight distance"},{"key":"b","text":"visibility limit"},{"key":"c","text":"head light distance"},{"key":"d","text":"sight distance"}],"answer":"d","explanation":"Sight distance is the length of road ahead visible to the driver at any instant. Stopping, overtaking and headlight sight distances are particular design values of it.","marks":1,"source":{"kind":"past","set":10,"question":42,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q42 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-10-052","src":"PAST-10-052","text":"The daily average traffic calculated based on a 30 days survey in 365 days is","options":[{"key":"a","text":"AADT"},{"key":"b","text":"ADT"},{"key":"c","text":"AAWT"},{"key":"d","text":"AWT"}],"answer":"b","explanation":"ADT is the average daily traffic from counts over a period shorter than a year, such as 30 days. AADT needs counts covering the whole year (365 days).","marks":1,"source":{"kind":"past","set":10,"question":52,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q52 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-10-065","src":"PAST-10-065","text":"The formula for mechanical extra widening in a road is","options":[{"key":"a","text":"\\(W_m = \\dfrac{nl^2}{2R}\\)"},{"key":"b","text":"\\(W_m = \\dfrac{nl^2}{127R}\\)"},{"key":"c","text":"\\(W_m = \\dfrac{nl^2}{254R}\\)"},{"key":"d","text":"\\(W_m = \\dfrac{nl^2}{R}\\)"}],"answer":"a","explanation":"Off-tracking of the rear wheels needs \\[W_m = \\dfrac{nl^2}{2R}\\] where \\(n\\) is the number of lanes, \\(l\\) the wheelbase and \\(R\\) the radius.","marks":2,"source":{"kind":"past","set":10,"question":65,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q65 · 2 marks"},"topic":"ACiE0902"},{"id":"PAST-10-075","src":"PAST-10-075","text":"Tie bars in rigid pavements are provided across","options":[{"key":"a","text":"contraction joints"},{"key":"b","text":"expansion joints"},{"key":"c","text":"longitudinal joints"},{"key":"d","text":"construction joints"}],"answer":"c","explanation":"Tie bars (deformed bars) across longitudinal joints keep adjacent slabs from separating. Dowel bars across transverse joints transfer load.","marks":2,"source":{"kind":"past","set":10,"question":75,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q75 · 2 marks"},"topic":"ACiE0905"},{"id":"PAST-10-076","src":"PAST-10-076","text":"In penetration macadam construction, the bitumen is","options":[{"key":"a","text":"sprayed after the aggregates are spread and compacted"},{"key":"b","text":"premixed with aggregates and then spread"},{"key":"c","text":"sprayed before the aggregates are spread and compacted"},{"key":"d","text":"none of the above"}],"answer":"a","explanation":"In penetration macadam, the coarse aggregate is laid and rolled first, then hot bitumen is sprayed so that it penetrates the voids, followed by key aggregate. Premixing describes bituminous macadam and concrete.","marks":2,"source":{"kind":"past","set":10,"question":76,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q76 · 2 marks"},"topic":"ACiE0906"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-10-001","src":"PAST-10-001","text":"The aspect ratio of a letter refers to the ratio of its","options":[{"key":"a","text":"height to width"},{"key":"b","text":"width to height"},{"key":"c","text":"length to width"},{"key":"d","text":"width to length"}],"answer":"a","explanation":"In lettering, the aspect ratio is the height : width proportion of the letters (for example 7:5 for vertical capitals).","marks":1,"source":{"kind":"past","set":10,"question":1,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q1 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-10-006","src":"PAST-10-006","text":"The professional code of conduct issued by NEC has","options":[{"key":"a","text":"6 articles"},{"key":"b","text":"8 articles"},{"key":"c","text":"7 articles"},{"key":"d","text":"9 articles"}],"answer":"b","explanation":"At the time of this paper, NEC's professional code of conduct had 8 articles. It has since been expanded to 11.","marks":1,"source":{"kind":"past","set":10,"question":6,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q6 · 1 mark"},"topic":"AALL1005"},{"id":"PAST-10-015","src":"PAST-10-015","text":"Capital budgeting is","options":[{"key":"a","text":"Reversible"},{"key":"b","text":"Unimportant"},{"key":"c","text":"Irreversible"},{"key":"d","text":"All of the above"}],"answer":"c","explanation":"Capital budgeting commits large funds to long-lived assets, and such decisions cannot be reversed without heavy loss. That is why they need careful appraisal.","marks":1,"source":{"kind":"past","set":10,"question":15,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q15 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-10-027","src":"PAST-10-027","text":"In PERT analysis, the time estimates of activities and the probability of their occurrence follow the","options":[{"key":"a","text":"normal distribution curve"},{"key":"b","text":"Poisson's distribution curve"},{"key":"c","text":"beta distribution curve"},{"key":"d","text":"none of the above"}],"answer":"c","explanation":"PERT assumes activity times follow a \\(\\beta\\)-distribution, giving \\[t_e = \\dfrac{t_o + 4t_m + t_p}{6}\\] The project duration is then treated as normally distributed.","marks":1,"source":{"kind":"past","set":10,"question":27,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q27 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-10-034","src":"PAST-10-034","text":"The President of NEA is an ex-officio member of which council?","options":[{"key":"a","text":"NEC"},{"key":"b","text":"SONA"},{"key":"c","text":"SCAEF"},{"key":"d","text":"NPC"}],"answer":"a","explanation":"Under the NEC Act, the President of the Nepal Engineers' Association is an ex-officio member of the Nepal Engineering Council.","marks":1,"source":{"kind":"past","set":10,"question":34,"marks":1,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q34 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-10-079","src":"PAST-10-079","text":"Which one is incorrect (about arrows in an activity network)?","options":[{"key":"a","text":"Arrows are drawn from left to right to scale"},{"key":"b","text":"Tail of arrow indicates start of activity"},{"key":"c","text":"Head of arrow indicates end of activity"},{"key":"d","text":"Each activity consumes time"}],"answer":"a","explanation":"In an activity-on-arrow network the tail marks the start and the head the end of an activity, and each real activity takes time. Arrow lengths are not drawn to any time scale, so (a) is incorrect.","marks":2,"source":{"kind":"past","set":10,"question":79,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q79 · 2 marks"},"topic":"AALL1003"},{"id":"PAST-10-080","src":"PAST-10-080","text":"The minimum time period allocated by GoN for formation of a new council after the dissolution of the current NEC is","options":[{"key":"a","text":"6 months"},{"key":"b","text":"3 months"},{"key":"c","text":"9 months"},{"key":"d","text":"1 year"}],"answer":"b","explanation":"Per the source key, a new council must be formed within three months after the existing council is dissolved.","marks":2,"source":{"kind":"past","set":10,"question":80,"marks":2,"date":"2080 Mangsir 22","shift":"2nd shift","reference":"Past Paper Set 10, Q80 · 2 marks"},"topic":"AALL1006"}]}]};
